// Run with the omp browser helper and an isolated Chromium tab.
export const captureCompact = async (mock) => await mock.run(async ({ page, tab, assert }) => {
  const dir = "/Users/joshuapare/omniview/screenshots/extension-registry-compact/";
  const saved = [];
  const check = async (s, m) => assert(await tab.evaluate(s), m);
  const shot = async (f) => {
    await page.screenshot({ path: dir + f });
    saved.push(f);
  };
  await page.goto("http://127.0.0.1:5278/");
  await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1 });
  await check(`document.querySelectorAll('[role=treeitem][aria-selected=true]').length===1`, "single tree selection");
  await shot("01-compact-tree-inspector.png");
  await page.click('[data-toggle="omniview/resource"]');
  await check(`__mock.state.collapsed.has('omniview/resource')`, "collapse");
  await page.click('[data-toggle="omniview/resource"]');
  await page.focus('[data-path="omniview/resource"]');
  await page.keyboard.press("ArrowLeft");
  await check(`__mock.state.collapsed.has('omniview/resource')`, "keyboard collapse");
  await page.keyboard.press("ArrowRight");
  await check(`!__mock.state.collapsed.has('omniview/resource')`, "keyboard expand");
  await page.select("#plugin", "kubernetes");
  await check(`__mock.state.plugin==='kubernetes'&&!document.querySelector('.tree').textContent.includes('global-search')`, "plugin filter");
  await shot("02-plugin-filter-same-tree.png");
  await page.click("#issues");
  await check(`__mock.state.issuesOnly&&document.querySelectorAll('.contribs tr.data').length===1`, "issue filter");
  await shot("03-issues-filter.png");
  await page.click('[data-problem="pending"]');
  await check("__mock.state.pending", "pending");
  await shot("04-pending-in-place.png");
  await page.click('[data-problem="crash"]');
  await page.click("#issues");
  await page.click('[data-tab="lookup"]');
  await page.click("#run");
  await check("__mock.state.evaluated", "lookup");
  await shot("05-context-lookup-docked.png");
  await page.select("#resource", "apps::v1::Deployment");
  await page.click("#run");
  await check(`__mock.state.resource==='apps::v1::Deployment'&&document.querySelector('.result').textContent.includes('Eligible, unproven')`, "Deployment");
  await page.click("#pause");
  await check("__mock.state.paused", "paused");
  await page.click("#pause");
  await check("!__mock.state.paused", "resumed");
  await page.select("#plugin", "core");
  await check(`document.querySelectorAll('.contribs tr.data').length===3&&!document.querySelector('[data-problem]')`, "core filter");
  await shot("06-core-filter.png");
  await page.type("#search", "no-such-point");
  await check(`document.querySelector('.editor').textContent.includes('No matching points')`, "empty state");
  await page.goto("http://127.0.0.1:5278/?theme=light");
  await shot("07-compact-light.png");
  await page.goto("http://127.0.0.1:5278/");
  await page.setViewport({ width: 1024, height: 768, deviceScaleFactor: 1 });
  await check("document.documentElement.scrollWidth===1024", "no horizontal overflow");
  await shot("08-compact-1024.png");
  return saved;
}, { timeout: 120 });
